1381	static void highbd_dr_prediction_z1_64xN_avx2(int N, uint16_t *dst,
1382	                                              ptrdiff_t stride,
1383	                                              const uint16_t *above,
1384	                                              int upsample_above, int dx) {
1385	  int x;
1386	
1387	  // here upsample_above is 0 by design of av1_use_intra_edge_upsample
1388	  (void)upsample_above;
1389	  const int frac_bits = 6;
1390	  const int max_base_x = ((64 + N) - 1);
1391	
1392	  // pre-filter above pixels
1393	  // store in temp buffers:
1394	  //   above[x] * 32 + 16
1395	  //   above[x+1] - above[x]
1396	  // final pixels will be caluculated as:
1397	  //   (above[x] * 32 + 16 + (above[x+1] - above[x]) * shift) >> 5
1398	  __m256i a0, a0_1, a1, a1_1, a32, a16;
1399	  __m256i a_mbase_x, diff, max_base_x256, base_inc256, mask256;
1400	
1401	  a16 = _mm256_set1_epi32(16);
1402	  a_mbase_x = _mm256_set1_epi16(above[max_base_x]);
1403	  max_base_x256 = _mm256_set1_epi16(max_base_x);
1404	
1405	  x = dx;
1406	  for (int r = 0; r < N; r++, dst += stride) {
1407	    __m256i b, res[2], res1;
1408	
1409	    int base = x >> frac_bits;
1410	    if (base >= max_base_x) {
1411	      for (int i = r; i < N; ++i) {
1412	        _mm256_storeu_si256((__m256i *)dst, a_mbase_x);  // save 32 values
1413	        _mm256_storeu_si256((__m256i *)(dst + 16), a_mbase_x);
1414	        _mm256_storeu_si256((__m256i *)(dst + 32), a_mbase_x);
1415	        _mm256_storeu_si256((__m256i *)(dst + 48), a_mbase_x);
1416	        dst += stride;
1417	      }
1418	      return;
1419	    }
1420	
1421	    __m256i shift = _mm256_srli_epi32(
1422	        _mm256_and_si256(_mm256_set1_epi32(x), _mm256_set1_epi32(0x3f)), 1);
1423	
1424	    __m128i a0_128, a0_1_128, a1_128, a1_1_128;
1425	    for (int j = 0; j < 64; j += 16) {
1426	      int mdif = max_base_x - (base + j);
1427	      if (mdif == 0) {
1428	        _mm256_storeu_si256((__m256i *)(dst + j), a_mbase_x);
1429	      } else {
1430	        a0_128 = _mm_loadu_si128((__m128i *)(above + base + j));
1431	        a1_128 = _mm_loadu_si128((__m128i *)(above + base + 1 + j));
1432	        a0 = _mm256_cvtepu16_epi32(a0_128);
1433	        a1 = _mm256_cvtepu16_epi32(a1_128);
1434	
1435	        diff = _mm256_sub_epi32(a1, a0);   // a[x+1] - a[x]
